//! crud 构建脚本 — 把**版本化 FK 索引产物**编译进 crate（方案 B，2026-09-24）
//!
//! 输入（唯一）：`fk-index.tsv`（本 crate 目录；或 `ALIOTH_FK_INDEX_ARTIFACT` 指定的绝对路径，
//! 供模型发布链路注入）。产物由 `scripts/generate-fk-index.ts` 生成，
//! 由 `scripts/check/check-fk-index.ts` 门禁与 DB 比对；Rust 源码不再被任何脚本改写。
//!
//! 输出：`$OUT_DIR/fk_index_generated.rs` —— `FK_INDEX_MODEL_VERSION` 常量 +
//! `FK_FORWARD` / `FK_REVERSE` 两个静态数组，由 `src/fk_index.rs` 以 `include!` 引入。
//!
//! 约束：
//! - **零 build-dependencies**（手写 TSV 解析，不引入 serde_json/yaml）；
//! - **保序**：不做二次排序（确定性由生成器的码元序负责，见 `scripts/lib/str-order.ts`），
//!   但校验分组键严格递增——`binary_search_by_key` 依赖该不变量，产物被手工改动即 fail-loud；
//! - 缺产物即编译失败（fail-loud）：报错信息带重建命令，避免「静默空索引」。

use std::env;
use std::fmt::Write as _;
use std::fs;
use std::path::{Path, PathBuf};

/// 产物的一行引用：forward = (field, target_table, local_key)；
/// reverse = (source_table, field, local_key)。语义由产物列序承担（见产物头部注释）。
type Entry = (String, String, String);

struct Parsed {
    model_version: String,
    forward: Vec<(String, Vec<Entry>)>,
    reverse: Vec<(String, Vec<Entry>)>,
}

fn main() {
    println!("cargo:rerun-if-env-changed=ALIOTH_FK_INDEX_ARTIFACT");
    let manifest_dir =
        PathBuf::from(env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR 缺失"));
    let artifact = match env::var("ALIOTH_FK_INDEX_ARTIFACT") {
        Ok(path) if !path.is_empty() => PathBuf::from(path),
        _ => manifest_dir.join("fk-index.tsv"),
    };
    println!("cargo:rerun-if-changed={}", artifact.display());

    let text = fs::read_to_string(&artifact).unwrap_or_else(|err| {
        panic!(
            "读取 FK 索引产物失败（{path}）：{err}\n\
             重建：bun scripts/generate-fk-index.ts --out {path}",
            path = artifact.display()
        )
    });
    let parsed = parse(&text, &artifact);

    let out_dir = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR 缺失"));
    fs::write(out_dir.join("fk_index_generated.rs"), render(&parsed))
        .expect("写出 fk_index_generated.rs 失败");
}

fn parse(text: &str, artifact: &Path) -> Parsed {
    let mut model_version = String::from("unknown");
    let mut forward: Vec<(String, Vec<Entry>)> = Vec::new();
    let mut reverse: Vec<(String, Vec<Entry>)> = Vec::new();

    for (idx, raw) in text.lines().enumerate() {
        let line_no = idx + 1;
        let line = raw.trim_end_matches('\r');
        if line.is_empty() {
            continue;
        }
        if let Some(rest) = line.strip_prefix('#') {
            if let Some(version) = rest.trim().strip_prefix("model_version:") {
                model_version = version.trim().to_string();
            }
            continue;
        }
        let cells: Vec<&str> = line.split('\t').collect();
        assert!(
            cells.len() == 5,
            "FK 索引产物第 {line_no} 行应为 5 列（kind/key/a/b/c），实际 {} 列：{line}",
            cells.len()
        );
        let groups = match cells[0] {
            "F" => &mut forward,
            "R" => &mut reverse,
            other => panic!("FK 索引产物第 {line_no} 行 kind 非法（应为 F/R）：{other}"),
        };
        let key = cells[1];
        let entry = (
            cells[2].to_string(),
            cells[3].to_string(),
            cells[4].to_string(),
        );
        match groups.last_mut() {
            Some((last_key, entries)) if last_key == key => entries.push(entry),
            Some((last_key, _)) => {
                assert!(
                    last_key.as_bytes() < key.as_bytes(),
                    "FK 索引产物分组键未按码元序递增（第 {line_no} 行 {last_key} ≮ {key}）\
                     —— binary_search_by_key 依赖有序，产物损坏即拒绝编译"
                );
                groups.push((key.to_string(), vec![entry]));
            }
            None => groups.push((key.to_string(), vec![entry])),
        }
    }

    for (label, groups) in [("FK_FORWARD", &forward), ("FK_REVERSE", &reverse)] {
        assert!(
            !groups.is_empty(),
            "{label} 为空 —— 产物 {artifact} 可能被截断或生成失败",
            artifact = artifact.display()
        );
    }

    Parsed {
        model_version,
        forward,
        reverse,
    }
}

fn render(parsed: &Parsed) -> String {
    let mut out = String::new();
    writeln!(
        out,
        "// @generated by crud/build.rs from fk-index.tsv — DO NOT EDIT"
    )
    .unwrap();
    writeln!(
        out,
        "// 重建：bun scripts/generate-fk-index.ts --out Framework/backend/crud/fk-index.tsv"
    )
    .unwrap();
    writeln!(
        out,
        "pub const FK_INDEX_MODEL_VERSION: &str = \"{}\";",
        escape(&parsed.model_version)
    )
    .unwrap();
    render_array(&mut out, "FK_FORWARD", &parsed.forward);
    render_array(&mut out, "FK_REVERSE", &parsed.reverse);
    out
}

fn render_array(out: &mut String, name: &str, groups: &[(String, Vec<Entry>)]) {
    writeln!(out).unwrap();
    writeln!(out, "#[rustfmt::skip]").unwrap();
    writeln!(out, "#[allow(clippy::type_complexity)]").unwrap();
    writeln!(
        out,
        "pub static {name}: &[(&str, &[(&str, &str, &str)])] = &["
    )
    .unwrap();
    for (key, entries) in groups {
        let body = entries
            .iter()
            .map(|(a, b, c)| format!("(\"{}\", \"{}\", \"{}\")", escape(a), escape(b), escape(c)))
            .collect::<Vec<_>>()
            .join(", ");
        writeln!(out, "    (\"{}\", &[{body}]),", escape(key)).unwrap();
    }
    writeln!(out, "];").unwrap();
}

/// Rust 字面量转义（产物字段为 PG 标识符，正常不含引号；此处防御性处理）。
fn escape(value: &str) -> String {
    value.replace('\\', "\\\\").replace('"', "\\\"")
}
